package com.gamehub.application.controller;
import com.gamehub.application.OperationsService; import java.time.Instant; import java.util.List;
public final class MatchController { private final OperationsService ops; public MatchController(OperationsService ops){this.ops=ops;} public List<Long> generate(long organizer,long tournament)throws Exception{return ops.generateMatches(organizer,tournament);} public void schedule(long organizer,long match,long station,Instant when)throws Exception{ops.scheduleMatch(organizer,match,station,when);} public void start(long organizer,long match)throws Exception{ops.startMatch(organizer,match);} public void result(long organizer,long match,int a,int b,long winner)throws Exception{ops.recordMatchResult(organizer,match,a,b,winner);} public void correct(long organizer,long match,int a,int b,long winner,String reason)throws Exception{ops.correctMatchResult(organizer,match,a,b,winner,reason);} }